#!/usr/bin/env bash
# Doc : extraits de code ancrés sur le texte (snippetStart/snippetEnd), et leur garde dans pnpm check.
# Prérequis : apply-docs-modules-1.sh. Pas de migration.
# Usage (racine du repo) : bash apply-fix-extraits-ancres.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/docs/lib/code.utils.ts" 2>/dev/null | grep -qF "export function resolveSnippetBounds"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "## Le jeton de réinitialisation" "apps/web/content/docs/dev/auth/le-modele-et-le-contrat.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-registre-tags.sh puis apply-docs-modules-1.sh"; exit 1; }
MODIFIED=("apps/web/src/features/docs/lib/code.utils.ts" "apps/web/src/features/docs/ui/CodeExample.tsx" "apps/web/src/features/docs/ui/CodeWalkthrough.tsx" "package.json")
CREATED=("scripts/check-doc-snippets.mjs")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "export function resolveSnippetBounds" "apps/web/src/features/docs/lib/code.utils.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "scripts"
base64 -d > "scripts/check-doc-snippets.mjs" <<'B64'
